ALTER TABLE source_records ALTER COLUMN connection_id DROP NOT NULL;
ALTER TABLE source_records ADD COLUMN kind text NOT NULL DEFAULT 'connector' CHECK(kind IN ('connector','upload','public'));
ALTER TABLE source_records ADD COLUMN deleted_at timestamptz;
ALTER TABLE source_records ADD CONSTRAINT source_kind_authority CHECK((kind='connector')=(connection_id IS NOT NULL));
CREATE TABLE document_requests(id uuid PRIMARY KEY,owner_id text NOT NULL REFERENCES auth_users(id),input_digest text NOT NULL,source_id uuid NOT NULL,kind text NOT NULL,state text NOT NULL,request jsonb NOT NULL,result jsonb,error_code text,workflow_run_id text,execution_attempts integer NOT NULL DEFAULT 0,provider_attempts integer NOT NULL DEFAULT 0,retry_after_ms integer,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE foundation_work_quota(day date NOT NULL,owner_id text NOT NULL,kind text NOT NULL,count integer NOT NULL,PRIMARY KEY(day,owner_id,kind));
CREATE TABLE document_jobs(id uuid PRIMARY KEY,owner_id text NOT NULL REFERENCES auth_users(id),conversation_id uuid NOT NULL REFERENCES agent_conversations(id),conversation_sequence integer NOT NULL,agent_config_version integer NOT NULL,input_digest text NOT NULL,request jsonb NOT NULL,source_refs jsonb NOT NULL,state text NOT NULL CHECK(state IN ('queued','running','paused','completed','cancelled','failed')),version integer NOT NULL DEFAULT 1,dispatches integer NOT NULL DEFAULT 1,workflow_run_id text NOT NULL,error_code text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE document_job_stages(job_id uuid NOT NULL REFERENCES document_jobs(id),stage integer NOT NULL CHECK(stage BETWEEN 1 AND 3),input_digest text NOT NULL,output jsonb NOT NULL,output_digest text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(job_id,stage));
CREATE TRIGGER immutable_document_job_stages BEFORE UPDATE OR DELETE ON document_job_stages FOR EACH ROW EXECUTE FUNCTION reject_agent_config_mutation();
CREATE TABLE document_job_attempts(job_id uuid NOT NULL REFERENCES document_jobs(id),version integer NOT NULL,stage integer NOT NULL,attempts integer NOT NULL DEFAULT 1,PRIMARY KEY(job_id,version,stage));
CREATE TABLE document_job_artifacts(job_id uuid PRIMARY KEY REFERENCES document_jobs(id),title text NOT NULL,markdown text NOT NULL,digest text NOT NULL,state text NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','saved')),saved_at timestamptz);
CREATE TABLE document_job_saves(job_id uuid PRIMARY KEY REFERENCES document_jobs(id),owner_id text NOT NULL,digest text NOT NULL,job_version integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TRIGGER immutable_document_job_saves BEFORE UPDATE OR DELETE ON document_job_saves FOR EACH ROW EXECUTE FUNCTION reject_agent_config_mutation();
CREATE TABLE result_events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,owner_id text NOT NULL REFERENCES auth_users(id),conversation_id uuid REFERENCES agent_conversations(id),job_id uuid REFERENCES document_jobs(id),event_key text NOT NULL,kind text NOT NULL,detail jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(owner_id,event_key));
CREATE INDEX result_events_owner ON result_events(owner_id,id);
CREATE TRIGGER immutable_result_events BEFORE UPDATE OR DELETE ON result_events FOR EACH ROW EXECUTE FUNCTION reject_agent_config_mutation();
CREATE TABLE result_consumers(owner_id text NOT NULL,consumer_id text NOT NULL,ack_cursor bigint NOT NULL DEFAULT 0,scope text NOT NULL DEFAULT '*',PRIMARY KEY(owner_id,consumer_id));
CREATE TABLE result_deliveries(id uuid PRIMARY KEY,owner_id text NOT NULL,consumer_id text NOT NULL,input_digest text NOT NULL,after_cursor bigint NOT NULL,next_cursor bigint NOT NULL,event_ids jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),acknowledged_at timestamptz,has_more boolean NOT NULL DEFAULT false);

CREATE FUNCTION protect_document_job_artifact() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Job artifacts are immutable'; END IF; IF NEW.job_id IS DISTINCT FROM OLD.job_id OR NEW.title IS DISTINCT FROM OLD.title OR NEW.markdown IS DISTINCT FROM OLD.markdown OR NEW.digest IS DISTINCT FROM OLD.digest OR OLD.state='saved' AND NEW.state<>'saved' THEN RAISE EXCEPTION 'Job artifacts are immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER immutable_document_job_artifacts BEFORE UPDATE OR DELETE ON document_job_artifacts FOR EACH ROW EXECUTE FUNCTION protect_document_job_artifact();
ALTER TABLE document_jobs ADD COLUMN template_version text NOT NULL DEFAULT 'document-compare-v1';
